CREATE TABLE commerce_payment_methods(id uuid PRIMARY KEY,tenant_id text NOT NULL,company_id text NOT NULL,name text NOT NULL,kind text NOT NULL,currency text NOT NULL,enabled boolean NOT NULL,requires_manual_verification boolean NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE commerce_payments(id uuid PRIMARY KEY,tenant_id text NOT NULL,company_id text NOT NULL,order_id uuid NOT NULL REFERENCES commerce_orders(id),method_id uuid NOT NULL REFERENCES commerce_payment_methods(id),amount_minor bigint NOT NULL CHECK(amount_minor>=0),currency text NOT NULL,status text NOT NULL,provider_id text NOT NULL,provider_event_id text,idempotency_key text NOT NULL,payload jsonb NOT NULL,submitted_at timestamptz NOT NULL,verified_at timestamptz,reconciled_at timestamptz,UNIQUE(tenant_id,company_id,idempotency_key),UNIQUE(tenant_id,company_id,provider_id,provider_event_id));
CREATE TABLE commerce_order_history(id uuid PRIMARY KEY,tenant_id text NOT NULL,company_id text NOT NULL,order_id uuid NOT NULL REFERENCES commerce_orders(id),status text NOT NULL,payload jsonb NOT NULL,occurred_at timestamptz NOT NULL);
CREATE INDEX commerce_payment_method_public ON commerce_payment_methods(company_id,enabled,name);
CREATE INDEX commerce_payment_status ON commerce_payments(company_id,status,submitted_at DESC);
CREATE INDEX commerce_order_history_timeline ON commerce_order_history(company_id,order_id,occurred_at);
ALTER TABLE commerce_payment_methods ENABLE ROW LEVEL SECURITY;ALTER TABLE commerce_payment_methods FORCE ROW LEVEL SECURITY;
ALTER TABLE commerce_payments ENABLE ROW LEVEL SECURITY;ALTER TABLE commerce_payments FORCE ROW LEVEL SECURITY;
ALTER TABLE commerce_order_history ENABLE ROW LEVEL SECURITY;ALTER TABLE commerce_order_history FORCE ROW LEVEL SECURITY;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['commerce_payment_methods','commerce_payments','commerce_order_history'] LOOP EXECUTE format('CREATE POLICY tenant_company_isolation ON %I USING(current_setting(''laex.platform_access'',true)=''on'' OR (tenant_id=current_setting(''laex.tenant_id'',true) AND company_id=current_setting(''laex.company_id'',true))) WITH CHECK(current_setting(''laex.platform_access'',true)=''on'' OR (tenant_id=current_setting(''laex.tenant_id'',true) AND company_id=current_setting(''laex.company_id'',true)))',t);END LOOP;END $$;
